package project

import (
	"cmp"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/edotau/claude-code/internal/textutil"
)

// docsBannerPrefix opens the banner of every generated file; prune/KEEP logic keys on it.
const docsBannerPrefix = "<!-- GENERATED by claude-code agents"

// DocsBanner is stamped at the top of every generated agent instruction file.
const DocsBanner = docsBannerPrefix + " sync — edit CLAUDE.md + agents/, then re-run. -->"

// instructionFiles maps an agent to the global instruction file its CLI reads from $HOME (relative path).
var instructionFiles = map[string]string{
	"codex":   filepath.Join(".codex", "AGENTS.md"),
	"copilot": filepath.Join(".copilot", "copilot-instructions.md"),
	"gemini":  filepath.Join(".gemini", "GEMINI.md"),
}

// docsPathsNote tells a vendor CLI how to resolve the relative paths CLAUDE.md names.
const docsPathsNote = "Paths in this file are relative to `~/.claude`."

// instructionSources are the root instruction files in lookup order: ours, the cross-agent name, then copilot's two.
var instructionSources = []string{"CLAUDE.md", "AGENTS.md",
	filepath.Join(".copilot", "copilot-instructions.md"), filepath.Join(".github", "copilot-instructions.md")}

// instructionSource returns the first instruction file present under root, or fs.ErrNotExist naming CLAUDE.md.
func instructionSource(root string) (string, error) {
	for _, name := range instructionSources {
		p := filepath.Join(root, name)
		if fi, err := os.Stat(p); err == nil && fi.Mode().IsRegular() {
			return p, nil
		}
	}
	return "", &fs.PathError{Op: "stat", Path: filepath.Join(root, instructionSources[0]), Err: fs.ErrNotExist}
}

// PortableCore lists the portable instruction core: the root instruction file, then unscoped rules/standards/*.md.
func PortableCore(root string) ([]string, error) {
	claude, err := instructionSource(root)
	if err != nil {
		return nil, fmt.Errorf("portable core: %w", err)
	}
	standards, err := unscopedStandards(root)
	if err != nil {
		return nil, err
	}
	paths := []string{claude}
	for _, s := range standards {
		paths = append(paths, s.path)
	}
	return paths, nil
}

type standard struct{ path, body string }

// unscopedStandards reads rules/standards/*.md without `paths:` frontmatter, sorted; a read failure names the file.
func unscopedStandards(root string) ([]standard, error) {
	files, err := filepath.Glob(filepath.Join(root, "rules", "standards", "*.md"))
	if err != nil {
		return nil, err
	}
	slices.Sort(files)
	var out []standard
	for _, f := range files {
		raw, err := os.ReadFile(f)
		if err != nil {
			return nil, fmt.Errorf("read standards %s: %w", f, err)
		}
		fm, body := textutil.ParseFrontmatter(string(raw))
		if fm["paths"] == nil {
			out = append(out, standard{f, body})
		}
	}
	return out, nil
}

// standardsSection renders the always-on rules/standards/*.md, H1s demoted.
func standardsSection(root string) (string, error) {
	standards, err := unscopedStandards(root)
	if err != nil || len(standards) == 0 {
		return "", err
	}
	var b strings.Builder
	for _, s := range standards {
		b.WriteString("\n" + demoteH1(strings.Trim(s.body, "\n")) + "\n")
	}
	return "\n## Standards\n" + b.String(), nil
}

// demoteH1 turns each `# ` heading outside a code fence into `## `.
func demoteH1(body string) string {
	lines := strings.Split(body, "\n")
	fenced := false
	for i, l := range lines {
		if strings.HasPrefix(l, "```") || strings.HasPrefix(l, "~~~") {
			fenced = !fenced
		} else if !fenced && strings.HasPrefix(l, "# ") {
			lines[i] = "#" + l
		}
	}
	return strings.Join(lines, "\n")
}

// renderDocs renders banner + CLAUDE.md verbatim + the always-on standards + a sorted `## Agents` index at root.
func renderDocs(root string, agents []Source) (content string, ok bool, err error) {
	src, err := instructionSource(root)
	if err != nil {
		return "", false, nil
	}
	conventions, err := os.ReadFile(src)
	if err != nil {
		return "", false, fmt.Errorf("read %s: %w", filepath.Base(src), err)
	}
	standards, err := standardsSection(root)
	if err != nil {
		return "", false, err
	}
	var b strings.Builder
	b.WriteString(DocsBanner + "\n\n" + docsPathsNote + "\n\n")
	b.WriteString(strings.TrimRight(string(conventions), "\n"))
	b.WriteString("\n" + standards)
	b.WriteString("\n## Agents\n\n")
	for _, a := range agents {
		fmt.Fprintf(&b, "- **%s** (`%s`)", a.Name(), cmp.Or(toString(a.frontmatter["model"]), "inherit"))
		if desc := firstSentence(cleanDescription(toString(a.frontmatter["description"]))); desc != "" {
			b.WriteString(" — ")
			b.WriteString(desc)
		}
		b.WriteString("\n")
	}
	return b.String(), true, nil
}
